assignments.value:
={{ (() => {
  const feedUrl = $('Split Out Sources').item.json.feed_url;
  const m = feedUrl.match(/^https:\/\/([^/]+)\/hcmRestApi.*siteNumber=([A-Za-z0-9_]+)/);
  const candidateSiteUrl = m ? `https://${m[1]}/hcmUI/CandidateExperience/en/sites/${m[2]}` : null;
  const list = $json.items?.[0]?.requisitionList ?? [];
  return list.map((job) => ({ ...job, candidateSiteUrl }));
})() }}

